begin;
create table platform.notification_recipients(notification_event_id uuid not null references platform.notification_events(id) on delete cascade,user_id uuid not null references platform.profiles(user_id) on delete cascade,read_at timestamptz,created_at timestamptz not null default statement_timestamp(),primary key(notification_event_id,user_id));
create index notification_recipients_user_unread_idx on platform.notification_recipients(user_id,created_at desc) where read_at is null;
alter table platform.notification_recipients enable row level security;alter table platform.notification_recipients force row level security;revoke all on platform.notification_recipients from public,anon,authenticated,service_role;
create or replace function platform_private.notification_user_is_authorized(p_user_id uuid,p_module_key text,p_resource_type text,p_resource_id text) returns boolean language sql stable security definer set search_path='' as $$select platform_private.is_account_approved(p_user_id) and (p_module_key='platform' or (p_module_key='reservations' and p_resource_type='event' and p_resource_id is not null and platform_private.user_has_module_permission_for(p_user_id,'reservations.booking.create','event',p_resource_id)) or (p_module_key not in('platform','reservations') and platform_private.user_has_module_permission_for(p_user_id,p_module_key||'.module.access',null,null)))$$;
revoke all on function platform_private.notification_user_is_authorized(uuid,text,text,text) from public,anon,authenticated,service_role;
create or replace function platform_private.list_my_notifications(p_actor_device_id uuid,p_limit integer) returns jsonb language plpgsql security definer set search_path='' as $$declare ctx jsonb;actor uuid;result jsonb;begin ctx:=nullif(pg_catalog.current_setting('platform.phase1c_context',true),'')::jsonb;if ctx is null or ctx->>'purpose'<>'PLATFORM_DEVICE_SESSION_DISPATCH' or (ctx->>'device_id')::uuid is distinct from p_actor_device_id then raise exception 'APPROVED_DEVICE_SESSION_REQUIRED' using errcode='42501';end if;actor:=(ctx->>'user_id')::uuid;if p_limit not between 1 and 100 then raise exception 'PLATFORM_NOTIFICATION_LIMIT_INVALID' using errcode='22023';end if;select coalesce(jsonb_agg(x.payload order by x.created_at desc),'[]'::jsonb) into result from(select r.created_at,jsonb_build_object('id',e.id,'eventType',e.event_type,'moduleKey',e.module_key,'resourceType',e.resource_type,'resourceId',e.resource_id,'title',e.title,'body',e.body,'targetUrl',e.target_url,'createdAt',e.created_at,'readAt',r.read_at)payload from platform.notification_recipients r join platform.notification_events e on e.id=r.notification_event_id where r.user_id=actor and platform_private.notification_user_is_authorized(actor,e.module_key,e.resource_type,e.resource_id) order by r.created_at desc limit p_limit)x;return jsonb_build_object('items',result,'unreadCount',(select count(*) from platform.notification_recipients r join platform.notification_events e on e.id=r.notification_event_id where r.user_id=actor and r.read_at is null and platform_private.notification_user_is_authorized(actor,e.module_key,e.resource_type,e.resource_id)));end$$;
revoke all on function platform_private.list_my_notifications(uuid,integer) from public,anon,authenticated,service_role;
create or replace function platform_private.mark_my_notification_read(p_actor_device_id uuid,p_notification_event_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare ctx jsonb;actor uuid;changed integer;begin ctx:=nullif(pg_catalog.current_setting('platform.phase1c_context',true),'')::jsonb;if ctx is null or ctx->>'purpose'<>'PLATFORM_DEVICE_SESSION_DISPATCH' or (ctx->>'device_id')::uuid is distinct from p_actor_device_id then raise exception 'APPROVED_DEVICE_SESSION_REQUIRED' using errcode='42501';end if;actor:=(ctx->>'user_id')::uuid;update platform.notification_recipients r set read_at=coalesce(r.read_at,statement_timestamp()) from platform.notification_events e where r.notification_event_id=p_notification_event_id and r.user_id=actor and e.id=r.notification_event_id and platform_private.notification_user_is_authorized(actor,e.module_key,e.resource_type,e.resource_id);get diagnostics changed=row_count;return jsonb_build_object('notificationEventId',p_notification_event_id,'read',changed>0);end$$;
revoke all on function platform_private.mark_my_notification_read(uuid,uuid) from public,anon,authenticated,service_role;
create or replace function platform_private.enqueue_notification(p_event_type text,p_module_key text,p_resource_type text,p_resource_id text,p_title text,p_body text,p_target_url text,p_dedupe_key text) returns jsonb language plpgsql security definer set search_path='' as $$declare event_id uuid;inserted boolean:=false;delivery_count integer;recipient_count integer;begin if coalesce(auth.jwt()->>'role','')<>'service_role' then raise exception 'PLATFORM_NOTIFICATION_BACKEND_REQUIRED' using errcode='42501';end if;if p_module_key not in('conference','reservations','warehouse','platform') or p_event_type !~ '^[a-z0-9_.-]{3,120}$' or p_resource_type !~ '^[a-z0-9_.-]{1,80}$' or char_length(coalesce(p_title,'')) not between 1 and 160 or char_length(coalesce(p_body,'')) not between 1 and 500 or char_length(coalesce(p_target_url,'')) not between 1 and 1000 or char_length(coalesce(p_dedupe_key,'')) not between 1 and 240 then raise exception 'PLATFORM_NOTIFICATION_EVENT_INVALID' using errcode='22023';end if;insert into platform.notification_events(event_type,module_key,resource_type,resource_id,title,body,target_url,dedupe_key)values(p_event_type,p_module_key,p_resource_type,p_resource_id,p_title,p_body,p_target_url,p_dedupe_key)on conflict(dedupe_key)do nothing returning id into event_id;if event_id is null then select id into event_id from platform.notification_events where dedupe_key=p_dedupe_key;else inserted:=true;end if;insert into platform.notification_recipients(notification_event_id,user_id)select event_id,pr.user_id from platform.profiles pr where platform_private.notification_user_is_authorized(pr.user_id,p_module_key,p_resource_type,p_resource_id)on conflict do nothing;get diagnostics recipient_count=row_count;insert into platform.notification_deliveries(notification_event_id,subscription_id)select event_id,s.id from platform.notification_push_subscriptions s join platform.notification_recipients r on r.notification_event_id=event_id and r.user_id=s.user_id where platform_private.notification_subscription_is_authorized(s.id,p_module_key,p_resource_type,p_resource_id)on conflict(notification_event_id,subscription_id)do nothing;get diagnostics delivery_count=row_count;return jsonb_build_object('notificationEventId',event_id,'created',inserted,'recipients',recipient_count,'queuedDeliveries',delivery_count);end$$;
revoke all on function platform_private.enqueue_notification(text,text,text,text,text,text,text,text) from public,anon,authenticated;grant execute on function platform_private.enqueue_notification(text,text,text,text,text,text,text,text) to service_role;
do $patch$ declare source_sql text;updated_sql text;needle text;begin source_sql:=pg_get_functiondef('platform.execute_device_operation(uuid,uuid,bytea,text,text,jsonb)'::regprocedure);if position('list_my_notifications' in source_sql)>0 then return;end if;needle:='when ''upsert_notification_push_subscription'' then';if position(needle in source_sql)=0 then raise exception 'PLATFORM_NOTIFICATION_INBOX_DISPATCHER_DRIFT';end if;updated_sql:=replace(source_sql,needle,'when ''list_my_notifications'' then -- list_my_notifications\nperform platform_private.require_exact_jsonb_keys(p_args,array[''p_limit'']);return platform_private.list_my_notifications(v_session.device_id,(p_args->>''p_limit'')::integer);\nwhen ''mark_my_notification_read'' then -- mark_my_notification_read\nperform platform_private.require_exact_jsonb_keys(p_args,array[''p_notification_event_id'']);return platform_private.mark_my_notification_read(v_session.device_id,(p_args->>''p_notification_event_id'')::uuid);\n'||needle);execute updated_sql;end$patch$;
commit;